import { createHash, randomUUID } from "node:crypto";
import { stringify as stringifyYaml, parse as parseYaml } from "yaml";
import type { NetworkDocument, NetworkInterface } from "../network/types.js";
import type { ExportWarning, MappingRow } from "./types.js";
import { EXPORT_MAX_DEVICES, EXPORT_MAX_LINKS, exporterFail } from "./limits.js";

export const CHANGE_ME = "CHANGE_ME";

export const HEADER_LINES = [
  "Generated by NerdGram from this diagram's network data.",
  "Credentials, images, and other values the diagram does not know are placeholders.",
  "Missing facts were omitted or marked. NerdGram did not connect to a device.",
  "Replace every CHANGE_ME before you use this file. Do not commit a real secret.",
];

export function isRecord(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

export function pushWarning(warnings: ExportWarning[], path: string, message: string): void {
  if (warnings.some((item) => item.path === path && item.message === message)) return;
  warnings.push({ path, message });
}

export function sortWarnings(warnings: readonly ExportWarning[]): ExportWarning[] {
  return [...warnings].sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : a.message < b.message ? -1 : a.message > b.message ? 1 : 0));
}

export type CommentStyle = "hash" | "xml" | "slash";

/** A leading comment. JSON has no comment syntax; those targets use warnings instead. */
export function commentBlock(style: CommentStyle, lines: readonly string[]): string {
  if (style === "xml") {
    const body = lines.map((line) => ` ${line}`).join("\n");
    return `<!--\n${body}\n-->\n`;
  }
  const mark = style === "slash" ? "//" : "#";
  return lines.map((line) => (line ? `${mark} ${line}` : mark)).join("\n") + "\n";
}

export function renderYaml(value: unknown): string {
  return stringifyYaml(value, { lineWidth: 0 });
}

export function parseYamlDocument(text: string): unknown {
  return parseYaml(text);
}

export function assertExportShape(document: NetworkDocument): void {
  if (document.devices.length > EXPORT_MAX_DEVICES || document.links.length > EXPORT_MAX_LINKS) {
    throw exporterFail(
      413,
      `A design export can have at most ${EXPORT_MAX_DEVICES} devices and ${EXPORT_MAX_LINKS} links.`,
      "too_large",
    );
  }
}

export function safeLabel(label: string): string {
  const trimmed = label.trim();
  if (!trimmed || /^-+$/.test(trimmed)) return "nerdgram";
  return trimmed;
}

export function fileName(label: string, extension: string): string {
  const stem = safeLabel(label).replace(/[\\/]/g, "-");
  if (!extension) return stem;
  return `${stem}.${extension}`;
}

export function cidr(address: string, prefix: number): string {
  return `${address}/${prefix}`;
}

/**
 * Cisco-style short names used when a link and an interface list disagree.
 * The long form is what the interface list usually stores.
 * Ethernet stays last so it does not swallow GigabitEthernet.
 */
const SHORT_FOR_LONG: { long: string; short: string }[] = [
  { long: "GigabitEthernet", short: "Gi" },
  { long: "TenGigabitEthernet", short: "Te" },
  { long: "FastEthernet", short: "Fa" },
  { long: "FortyGigabitEthernet", short: "Fo" },
  { long: "HundredGigE", short: "Hu" },
  { long: "TwentyFiveGigE", short: "Twe" },
  { long: "AppGigabitEthernet", short: "Ap" },
  { long: "Port-channel", short: "Po" },
  { long: "Loopback", short: "Lo" },
  { long: "Vlan", short: "Vl" },
  { long: "Tunnel", short: "Tu" },
  { long: "Serial", short: "Se" },
  { long: "Ethernet", short: "Eth" },
];

function expandInterface(name: string): string {
  for (const pair of SHORT_FOR_LONG) {
    const match = new RegExp(`^${pair.short}(?=\\d)`, "i").exec(name);
    if (match) return `${pair.long}${name.slice(match[0].length)}`;
  }
  return name;
}

function shortenInterface(name: string): string {
  for (const pair of SHORT_FOR_LONG) {
    if (name.toLowerCase().startsWith(pair.long.toLowerCase())) {
      return `${pair.short}${name.slice(pair.long.length)}`;
    }
  }
  return name;
}

export type ResolvedLink = {
  index: number;
  aDevice: string;
  aInterface: string;
  bDevice: string;
  bInterface: string;
  inferred: boolean;
  unresolved: boolean;
  label: string;
};

/** Resolve both ends of every link. Unresolved ends stay, with a warning, and no peer is invented. */
export function resolveLinks(document: NetworkDocument, warnings: ExportWarning[]): ResolvedLink[] {
  return document.links.map((link, index) => {
    const a = resolveInterface(link.a.device, link.a.interface, document.interfaces);
    const b = resolveInterface(link.b.device, link.b.interface, document.interfaces);
    if (a.unresolved) {
      pushWarning(
        warnings,
        `/links/${index}/a/interface`,
        `Link interface "${link.a.interface}" on ${link.a.device} did not match an interface name. The link name was kept.`,
      );
    }
    if (b.unresolved) {
      pushWarning(
        warnings,
        `/links/${index}/b/interface`,
        `Link interface "${link.b.interface}" on ${link.b.device} did not match an interface name. The link name was kept.`,
      );
    }
    if (link.inferred) {
      pushWarning(
        warnings,
        `/links/${index}`,
        `Link ${link.a.device}:${a.name} to ${link.b.device}:${b.name} is inferred and is not a proven cable.`,
      );
    }
    return {
      index,
      aDevice: link.a.device,
      aInterface: a.name,
      bDevice: link.b.device,
      bInterface: b.name,
      inferred: link.inferred,
      unresolved: a.unresolved || b.unresolved,
      label: link.label,
    };
  });
}

export type ResolvedInterface = {
  /** Name to write. The interface-list spelling when one matched. */
  name: string;
  /** True when no interface on the device matched, even after abbreviations. */
  unresolved: boolean;
};

/**
 * Match a link endpoint to an interface on that device.
 * Exact, then case-insensitive, then the abbreviation table above.
 * An unmatched name is kept and marked unresolved. Nothing is invented.
 */
export function resolveInterface(device: string, rawName: string, interfaces: readonly NetworkInterface[]): ResolvedInterface {
  const owned = interfaces.filter((item) => item.device === device);
  const exact = owned.find((item) => item.name === rawName);
  if (exact) return { name: exact.name, unresolved: false };
  const folded = owned.find((item) => item.name.toLowerCase() === rawName.toLowerCase());
  if (folded) return { name: folded.name, unresolved: false };
  const expanded = expandInterface(rawName);
  const fromShort = owned.find((item) => item.name.toLowerCase() === expanded.toLowerCase());
  if (fromShort) return { name: fromShort.name, unresolved: false };
  const fromLong = owned.find((item) => shortenInterface(item.name).toLowerCase() === rawName.toLowerCase());
  if (fromLong) return { name: fromLong.name, unresolved: false };
  return { name: rawName, unresolved: true };
}

export type MapRow = {
  platform?: string;
  role?: string;
  model?: string;
  values: Record<string, string>;
};

function same(left: string | undefined, right: string): boolean {
  if (left == null || left === "") return true;
  return left.trim().toLowerCase() === right.trim().toLowerCase();
}

function specificity(row: MapRow): number {
  return (row.platform ? 1 : 0) + (row.role ? 1 : 0) + (row.model ? 1 : 0);
}

/**
 * Most specific matching row wins. Override rows are considered first, so an
 * operator row beats a built-in row of the same specificity.
 * A row with no platform, role, or model matches everything and is the fallback.
 */
export function lookupMapping(
  builtIn: readonly MapRow[],
  device: { platform: string; role: string; model: string },
  override: readonly MappingRow[] | null,
): Record<string, string> | null {
  const extra: MapRow[] = (override ?? []).map((row) => ({
    platform: row.platform,
    role: row.role,
    model: row.model,
    values: Object.fromEntries(Object.entries(row).filter(([key]) => key !== "platform" && key !== "role" && key !== "model")),
  }));
  const ranked = [
    ...extra.map((row, index) => ({ row, index, override: true })),
    ...builtIn.map((row, index) => ({ row, index, override: false })),
  ];
  const matches = ranked.filter(
    (item) => same(item.row.platform, device.platform) && same(item.row.role, device.role) && same(item.row.model, device.model),
  );
  if (matches.length === 0) return null;
  matches.sort((a, b) => {
    const score = specificity(b.row) - specificity(a.row);
    if (score !== 0) return score;
    if (a.override !== b.override) return a.override ? -1 : 1;
    return a.index - b.index;
  });
  return matches[0]?.row.values ?? null;
}

export function mappingRowsFromUnknown(value: unknown): MappingRow[] | null {
  if (value == null) return null;
  if (!Array.isArray(value)) return null;
  const rows: MappingRow[] = [];
  for (const item of value) {
    if (!isRecord(item)) continue;
    const row: MappingRow = {};
    for (const [key, raw] of Object.entries(item)) {
      if (typeof raw === "string") row[key] = raw;
      else if (typeof raw === "number" || typeof raw === "boolean") row[key] = String(raw);
    }
    if (Object.keys(row).length > 0) rows.push(row);
  }
  return rows;
}

/** A whole mapping file keyed by exporter id. Unknown keys are ignored by other targets. */
export function mappingForTarget(document: unknown, id: string): MappingRow[] | null {
  if (!isRecord(document)) return null;
  return mappingRowsFromUnknown(document[id]);
}

export function parseMappingText(text: string): unknown {
  const trimmed = text.replace(/^\uFEFF/, "").trim();
  if (!trimmed) return null;
  try {
    return JSON.parse(trimmed) as unknown;
  } catch {
    return parseYaml(trimmed) as unknown;
  }
}

/** Inventory group names: letters, digits, underscores, and no leading digit. */
export function safeGroupName(name: string): string {
  const cleaned = name
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9_]+/g, "_")
    .replace(/^_+|_+$/g, "");
  if (!cleaned) return "ungrouped";
  if (/^\d/.test(cleaned)) return `g_${cleaned}`;
  return cleaned;
}

export function stableUuid(seed: string): string {
  const hex = createHash("sha256").update(seed).digest("hex");
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-4${hex.slice(13, 16)}-a${hex.slice(17, 20)}-${hex.slice(20, 32)}`;
}

export function randomId(): string {
  return randomUUID();
}

/** CRC-32 and a stored (uncompressed) zip. Multi-file targets download as one archive. */
export function zipStore(files: readonly { name: string; text: string }[]): Buffer {
  const locals: Buffer[] = [];
  const centrals: Buffer[] = [];
  let offset = 0;
  for (const file of files) {
    const name = Buffer.from(file.name.replace(/\\/g, "/"), "utf8");
    const data = Buffer.from(file.text, "utf8");
    const crc = crc32(data);
    const local = Buffer.alloc(30 + name.length);
    local.writeUInt32LE(0x04034b50, 0);
    local.writeUInt16LE(20, 4);
    local.writeUInt16LE(0, 6);
    local.writeUInt16LE(0, 8);
    local.writeUInt16LE(0, 10);
    local.writeUInt16LE(0, 12);
    local.writeUInt32LE(crc, 14);
    local.writeUInt32LE(data.length, 18);
    local.writeUInt32LE(data.length, 22);
    local.writeUInt16LE(name.length, 26);
    local.writeUInt16LE(0, 28);
    name.copy(local, 30);
    locals.push(local, data);
    const central = Buffer.alloc(46 + name.length);
    central.writeUInt32LE(0x02014b50, 0);
    central.writeUInt16LE(20, 4);
    central.writeUInt16LE(20, 6);
    central.writeUInt16LE(0, 8);
    central.writeUInt16LE(0, 10);
    central.writeUInt16LE(0, 12);
    central.writeUInt16LE(0, 14);
    central.writeUInt32LE(crc, 16);
    central.writeUInt32LE(data.length, 20);
    central.writeUInt32LE(data.length, 24);
    central.writeUInt16LE(name.length, 28);
    central.writeUInt16LE(0, 30);
    central.writeUInt16LE(0, 32);
    central.writeUInt16LE(0, 34);
    central.writeUInt16LE(0, 36);
    central.writeUInt32LE(0, 38);
    central.writeUInt32LE(offset, 42);
    name.copy(central, 46);
    centrals.push(central);
    offset += local.length + data.length;
  }
  const centralBuf = Buffer.concat(centrals);
  const end = Buffer.alloc(22);
  end.writeUInt32LE(0x06054b50, 0);
  end.writeUInt16LE(0, 4);
  end.writeUInt16LE(0, 6);
  end.writeUInt16LE(files.length, 8);
  end.writeUInt16LE(files.length, 10);
  end.writeUInt32LE(centralBuf.length, 12);
  end.writeUInt32LE(offset, 16);
  end.writeUInt16LE(0, 20);
  return Buffer.concat([...locals, centralBuf, end]);
}

const CRC_TABLE = (() => {
  const table = new Uint32Array(256);
  for (let index = 0; index < 256; index += 1) {
    let crc = index;
    for (let bit = 0; bit < 8; bit += 1) crc = crc & 1 ? 0xedb88320 ^ (crc >>> 1) : crc >>> 1;
    table[index] = crc >>> 0;
  }
  return table;
})();

function crc32(data: Buffer): number {
  let crc = 0xffffffff;
  for (const byte of data) crc = CRC_TABLE[(crc ^ byte) & 0xff]! ^ (crc >>> 8);
  return (crc ^ 0xffffffff) >>> 0;
}
